// Extrae el texto de la respuesta de Claude y valida contra el esquema lacaniano
const response = $input.first().json;
const rawText = response?.content?.[0]?.text || '';

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  return [{ json: { status: 'error', validationDetails: ['La respuesta de Claude no es JSON válido: ' + e.message], raw: rawText } }];
}

const requiredFields = ['semblante_imaginario', 'falta_en_el_otro', 'objeto_a', 'nombre_del_padre', 'discurso_operatorio', 'sintoma_anudamiento'];
const validDiscursos = ['Amo', 'Universidad', 'Histérica', 'Analista'];
const errors = [];

const data = parsed.lacanian_data || {};
for (const field of requiredFields) {
  if (!data[field] || typeof data[field] !== 'string' || data[field].trim() === '') {
    errors.push(`Campo faltante o vacío: ${field}`);
  }
}
if (data.discurso_operatorio && !validDiscursos.includes(data.discurso_operatorio)) {
  errors.push(`discurso_operatorio inválido: ${data.discurso_operatorio}`);
}

if (errors.length > 0 || parsed.status === 'error') {
  return [{ json: { status: 'error', validationDetails: errors.length ? errors : (parsed.validationDetails || ['Error no especificado']) } }];
}

return [{ json: { status: 'success', lacanian_data: data, validationDetails: [] } }];
